
const _savedScannerTf=localStorage.getItem('PMA_SCANNER_TF');if(!localStorage.getItem('PMA_SCANNER_DEFAULT_V2')){localStorage.setItem('PMA_SCANNER_TF','15m');localStorage.setItem('PMA_SCANNER_DEFAULT_V2','1')}const state={user:null,page:localStorage.getItem('PMA_CURRENT_PAGE')||'home',market:localStorage.getItem('PMA_MARKET')||'Forex',symbol:localStorage.getItem('PMA_SYMBOL')||'EURUSD',ref:new URLSearchParams(location.search).get('ref')||'',notif:[],scannerTimer:null,entryTimer:null,dayTradeTimer:null,notifTimer:null,browserAlertsReady:false,serverVerified:false,restoringReload:false,notificationCategory:'All',scannerStyle:localStorage.getItem('PMA_SCANNER_STYLE')||'Scalping',scannerTf:localStorage.getItem('PMA_SCANNER_TF')||'15m',scannerLock:null,lastTrends:null};
const markets={Forex:['EURUSD','GBPUSD','USDJPY','GBPJPY','AUDUSD','USDCAD','USDCHF','NZDUSD','EURJPY','EURGBP','EURCHF','GBPCHF','AUDJPY','CADJPY'],Indices:['US30','NAS100','SPX500','GER40','UK100','FRA40','JP225'],Metals:['XAUUSD','XAGUSD','XPTUSD','XPDUSD'],Crypto:['BTCUSD','ETHUSD','SOLUSD','XRPUSD','LTCUSD'],Commodities:['USOIL','UKOIL','NATGAS','COPPER']};
const API_BASE=(localStorage.getItem('PMA_API_BASE')||'https://pips-master-frontend.onrender.com').replace(/\/$/,'');
function makeApiError(message,status=0,detail=''){const e=new Error(message||'Request failed');e.status=status;e.detail=detail||message;return e}
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};const token=localStorage.getItem('PMA_TOKEN');if(token)headers.Authorization='Bearer '+token;const controller=new AbortController();const timeoutMs=opts.timeoutMs||10000;const timer=setTimeout(()=>controller.abort(),timeoutMs);try{const clean={...opts};delete clean.timeoutMs;const r=await fetch(API_BASE+'/api'+path,{...clean,headers,signal:controller.signal,cache:'no-store'});const x=await r.json().catch(()=>({}));if(!r.ok)throw makeApiError(x.detail||'Request failed',r.status,x.detail||'');return x}catch(e){if(e?.name==='AbortError')throw makeApiError('The PMA server took too long to respond. Please try again.',408,'TIMEOUT');if(e instanceof TypeError)throw makeApiError('The PMA server could not be reached. Check the deployed backend connection.',0,'NETWORK_ERROR');throw e}finally{clearTimeout(timer)}}
async function apiFast(path,opts={}){return api(path,{...opts,timeoutMs:opts.timeoutMs||10000})}
async function apiRetry(path,opts={},retries=2){let last;for(let i=0;i<=retries;i++){try{return await api(path,opts)}catch(e){last=e;if(e?.status===401||e?.status===403||e?.status===400||e?.status===503||e?.detail==='EMAIL_VERIFY_REQUIRED')break;if(i<retries)await new Promise(r=>setTimeout(r,500*(i+1)))}}throw last}
async function apiLogin(path,opts={}){return api(path,{...opts,timeoutMs:30000})}
function prefetchDayTradeCaches(){if(!state.user)return;const tf=state.dayTf||localStorage.getItem('PMA_DAY_TF')||'15m';const ordered=Object.keys(markets).filter(m=>m!==state.market);ordered.forEach((m,i)=>{setTimeout(()=>{const key='PMA_DAYTRADE_'+m+'_'+tf;const symbols=markets[m][0];apiFast('/day-trade/plan?market='+encodeURIComponent(m)+'&symbols='+encodeURIComponent(symbols)+'&timeframe='+encodeURIComponent(tf)).then(x=>localStorage.setItem(key,JSON.stringify(x))).catch(()=>{})},i*900)})}
function fastCached(key){return readJson('PMA_FAST_'+key,null)}
function saveFastCached(key,value){try{localStorage.setItem('PMA_FAST_'+key,JSON.stringify(value))}catch(e){}}
function show(id){if(id==='login'){localStorage.removeItem('PMA_TOKEN');state.user=null;state.serverVerified=false;liEmail.value='';liPass.value='';liMsg.textContent='';}document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById(id).classList.add('active');if(id==='signup'&&state.ref){suMsg.textContent='Referral code: '+state.ref;suMsg.className='form-msg ok'}if(id==='app')page(state.page||'home',true)}
function applyTheme(){const theme=localStorage.getItem('PMA_THEME')||'dark';document.body.classList.toggle('light',theme==='light');const b=document.getElementById('themeToggle');if(b){b.innerHTML=theme==='light'?'<span class="theme-icon" aria-hidden="true">☀️</span><span>Light mode</span>':'<span class="theme-icon" aria-hidden="true">🌙</span><span>Dark mode</span>';b.setAttribute('aria-label','Switch to '+(theme==='light'?'dark':'light')+' mode');}}
function toggleTheme(){const next=(localStorage.getItem('PMA_THEME')||'dark')==='light'?'dark':'light';localStorage.setItem('PMA_THEME',next);applyTheme()}

function togglePassword(id,btn){const el=document.getElementById(id);el.type=el.type==='password'?'text':'password';btn.textContent=el.type==='password'?'👁️':'🙈'}
function validateSignup(){if(!document.getElementById('suPass'))return;const p=suPass.value,p2=suPass2.value;suPassMsg.textContent=p.length===0?'':'Password must be at least 8 characters.';suPassMsg.className='form-msg '+(p.length>=8?'ok':'error');suMatchMsg.textContent=p2.length===0?'':(p===p2?'Passwords match.':'Passwords do not match.');suMatchMsg.className='form-msg '+(p2.length===0?'':(p===p2?'ok':'error'))}
function saveLocalUser(u){localStorage.setItem('PMA_LOCAL_USER',JSON.stringify(u));state.user=u;localStorage.setItem('PMA_USER_PROFILE',JSON.stringify(u))}
function readJson(key,fallback=[]){try{return JSON.parse(localStorage.getItem(key)||JSON.stringify(fallback))}catch{return fallback}}
function addNotification(title,text,type='info',targetPage=''){const n={id:Date.now()+Math.random(),title,text,type,target_page:targetPage||notificationTarget({type}),time:new Date().toLocaleString(),read:false};const history=readJson('PMA_NOTIFICATION_HISTORY',[]);history.unshift(n);localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history.slice(0,250)));const inbox=readJson('PMA_NOTIFICATION_INBOX',[]);inbox.unshift(n);localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(inbox.slice(0,60)));state.notif=history;updateNotifBadge()}
function migrateNotifications(){const old=readJson('PMA_NOTIFICATIONS',[]);if(old.length&&!localStorage.getItem('PMA_NOTIFICATION_HISTORY')){localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(old));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(old));}}
function getNotificationHistory(){migrateNotifications();return readJson('PMA_NOTIFICATION_HISTORY',[])}
function getNotificationInbox(){migrateNotifications();return readJson('PMA_NOTIFICATION_INBOX',[])}
function updateNotifBadge(){const dismissed=new Set(readJson('PMA_NOTIFICATION_DISMISSED_IDS',[]).map(String));const n=getNotificationHistory().filter(x=>!dismissed.has(String(x.server_id||x.id))&&!x.read);const b=document.getElementById('notifBadge');if(b)b.textContent=String(n.length)}
function loadLocalUser(){try{return JSON.parse(localStorage.getItem('PMA_LOCAL_USER')||'null')}catch{return null}}
async function signup(){validateSignup();if(!suUser.value.trim()||!suName.value.trim()||!suEmail.value.trim()){suMsg.textContent='Please complete all required fields.';suMsg.className='form-msg error';return}if(suPass.value.length<8||suPass.value!==suPass2.value){suMsg.textContent=suPass.value!==suPass2.value?'Passwords do not match.':'Please fix the password above.';suMsg.className='form-msg error';return}suMsg.textContent='Creating your account…';suMsg.className='form-msg ok';try{const email=suEmail.value.trim().toLowerCase();const x=await apiRetry('/auth/signup',{method:'POST',body:JSON.stringify({username:suUser.value,full_name:suName.value,email,password:suPass.value,confirm_password:suPass2.value,referral:state.ref})},2);localStorage.removeItem('PMA_TOKEN');state.user=null;state.serverVerified=false;show('verifyEmail');veEmail.value=email;veCode.value='';veMsg.textContent=x.message||'Check your email for the 6-digit verification code.';veMsg.className='form-msg ok'}catch(e){suMsg.textContent=e?.message||'The PMA server could not create your account. Please try again.';suMsg.className='form-msg error'}}
async function login(){const email=liEmail.value.trim().toLowerCase(),pass=liPass.value;if(!email||!pass){liMsg.textContent='Enter your email and password.';liMsg.className='form-msg error';return}liMsg.textContent='Checking your account…';liMsg.className='form-msg ok';try{await apiLogin('/auth/login',{method:'POST',body:JSON.stringify({email,password:pass})});show('verifyEmail');veEmail.value=email;veCode.value='';veMsg.textContent='A fresh 6-digit verification code has been sent to your email. Enter it to finish signing in.';veMsg.className='form-msg ok';return}catch(e){if(e?.status===403||String(e?.detail||e?.message||'')==='EMAIL_VERIFY_REQUIRED'){show('verifyEmail');veEmail.value=email;veCode.value='';veMsg.textContent='A fresh 6-digit verification code has been sent to your email. Enter it to finish signing in.';veMsg.className='form-msg ok';return}liMsg.textContent=e?.message||'Login failed. Check your email and password.';liMsg.className='form-msg error'}}
async function verifyEmailCode(){const email=veEmail.value.trim().toLowerCase(),code=veCode.value.trim();if(!email||code.length!==6){veMsg.textContent='Enter your email and the 6-digit code.';veMsg.className='form-msg error';return}veMsg.textContent='Verifying…';veMsg.className='form-msg ok';try{const x=await api('/auth/verify-email',{method:'POST',body:JSON.stringify({email,code})});if(x.token&&x.user){state.user=x.user;state.serverVerified=true;localStorage.setItem('PMA_TOKEN',x.token);saveLocalUser(x.user);addNotification('Signed in securely','Your email was verified and your PMA session is active.','security');veMsg.textContent='Verified. Opening PMA…';setTimeout(()=>enterApp(true),250);return}veMsg.textContent=x.message||'Email verified successfully.';veMsg.className='form-msg ok'}catch(e){veMsg.textContent=e?.message||'Verification failed. Please try again.';veMsg.className='form-msg error'}}
async function resendVerificationCode(){const email=veEmail.value.trim().toLowerCase();if(!email){veMsg.textContent='Enter your email first.';veMsg.className='form-msg error';return}veMsg.textContent='Sending a new code…';veMsg.className='form-msg ok';try{const x=await api('/auth/resend-verification',{method:'POST',body:JSON.stringify({email})});veMsg.textContent=x.message||'A new verification code has been sent.';veMsg.className='form-msg ok'}catch(e){veMsg.textContent=e?.message||'Could not send a new verification code.';veMsg.className='form-msg error'}}
