function scannerTimeframes(style){return ['1m','5m','15m','1h','4h','1d']}
function setScannerPreference(style,tf){state.scannerStyle=style;state.scannerTf=tf;localStorage.setItem('PMA_SCANNER_STYLE',style);localStorage.setItem('PMA_SCANNER_TF',tf);state.scannerLock=null;state.lastTrends=null;renderScanner();scanMarket()}
function signals(){const tfs=scannerTimeframes(state.scannerStyle);if(!tfs.includes(state.scannerTf))state.scannerTf=tfs[0];return `<div class="section"><h1 class="section-title">Automated Market Scanner</h1><p class="lead">Choose how you want the scanner to analyse the selected market. Trigger timeframe is separate from the multi-timeframe context below.</p><div class="card"><div class="scanner-preferences"><div class="field"><label>Trading style</label><select id="scannerStyle" onchange="setScannerPreference(this.value,state.scannerTf)">${['Scalping','Day Trading','Swing Trading'].map(x=>`<option ${x===state.scannerStyle?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Scanner trigger timeframe</label><select id="scannerTf" onchange="setScannerPreference(state.scannerStyle,this.value)">${tfs.map(x=>`<option ${x===state.scannerTf?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="filters"><button class="btn alt" onclick="scanMarket()">↻ Refresh</button><button class="btn ghost" onclick="page('daytrade')">Open Day Trade</button></div><span id="scannerStatus" class="muted" style="display:block;margin-top:8px;font-size:12px">Checking market data…</span></div><div class="card"><div class="chips">${Object.keys(markets).map(x=>`<button class="chip ${state.market===x?'active':''}" onclick="state.market='${x}';state.symbol='';page('signals')">${x}</button>`).join('')}</div><div class="filters"><input id="symbolSearch" class="search" placeholder="Search a supported symbol, e.g. EURUSD, GBPUSD, XAUUSD" oninput="renderScanner()"><button class="btn alt" onclick="clearSymbolSearch()">Clear</button></div><div id="symbolResults" class="chips"></div></div><div class="card trend-panel"><h3>Multi-timeframe trend</h3><p class="muted">These cards provide market context; they are not the scanner trigger timeframe.</p><div id="trendGrid" class="trend-grid"></div></div><div class="card tv-wrap"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><b>TradingView Live Chart</b><div class="muted" id="tvSymbolLabel">${state.symbol||markets[state.market][0]}</div></div><span class="pill" id="tvTfLabel">${state.scannerTf}</span></div><iframe id="tvFrame" title="TradingView chart" allowtransparency="true" scrolling="no"></iframe></div><div id="scannerArea"></div><div class="card" style="margin-top:16px"><h3>Closest monitored setups</h3><p class="muted">Ranked by setup state and estimated travel to the next opposing zone.</p><div id="nearbySetups"></div></div></div>`}
function fmtDuration(mins){if(mins==null)return '—';const m=Math.max(0,Math.round(mins));if(m<60)return m+' min';const h=Math.floor(m/60),r=m%60;return h+'h'+(r?' '+r+'m':'')}
function formatEntryEta(c){return c?.candles_to_next_zone!=null?`≈ ${c.candles_to_next_zone} candles • ${fmtDuration(c.estimated_minutes_to_next_zone)}`:'Waiting for verified data…'}
function setupStrengthValue(v){const n=Number(v);if(!Number.isFinite(n))return 0;return Math.max(0,Math.min(80,Math.round(n)))}
function setupStrengthLabel(v){const n=setupStrengthValue(v);if(n>=75)return n+'% — Strong confluence';if(n>=70)return n+'% — Confirmed confluence';if(n>0)return n+'% — Waiting for confirmation';return '0% — Waiting for confirmation'}
function startScanner(){clearInterval(state.scannerTimer);renderScanner();scanMarket();state.scannerTimer=setInterval(scanMarket,30000)}
function clearSymbolSearch(){const el=document.getElementById('symbolSearch');if(el)el.value='';renderScanner()}
function selectScannerSymbol(symbol){state.symbol=symbol;localStorage.setItem('PMA_SYMBOL',symbol);renderScanner();scanMarket()}
function renderScanner(){const area=document.getElementById('scannerArea');if(!area)return;const q=(document.getElementById('symbolSearch')?.value||'').toUpperCase();const syms=markets[state.market].filter(x=>x.includes(q));document.getElementById('symbolResults').innerHTML=syms.map(x=>`<button class="chip ${state.symbol===x?'active':''}" onclick="selectScannerSymbol('${x}')">${x}</button>`).join('')||'<span class="muted">No matching supported symbol.</span>';const selected=state.symbol||syms[0]||markets[state.market][0];updateTradingView(selected);area.innerHTML=`<div class="card closest signal"><div class="pill">● PMA AUTOMATED SIGNAL ENGINE</div><div class="scanner-heading"><div><h2 id="selectedSymbol">${selected}</h2><div class="muted">${state.market}</div></div><div id="selectedDirection" class="signal-badge">WAITING</div></div><div id="selectedEta" class="eta">PMA engine warming — cached/verified market data will appear immediately when available…</div><p id="selectedZone" class="muted">Analysing trend, structure, supply/demand and support/resistance.</p><div id="selectedMeta" class="zone-badge">Verified data only</div><div id="selectedStats" class="scanner-stats"></div><div id="selectedDetails" class="scanner-details"></div></div>`;renderTrendGrid()}
function updateTradingView(symbol){const frame=document.getElementById('tvFrame');if(!frame)return;const tv=state.market==='Forex'?'FX:'+symbol:(state.market==='Indices'?'CAPITALCOM:'+symbol:(state.market==='Metals'?'OANDA:'+symbol:(state.market==='Crypto'?'COINBASE:'+symbol:'TVC:'+symbol)));const tvIntervals={'1m':'1','5m':'5','15m':'15','1h':'1H','4h':'4H','1d':'1D'};const interval=tvIntervals[state.scannerTf]||'5';document.getElementById('tvSymbolLabel').textContent=symbol;const tf=document.getElementById('tvTfLabel');if(tf)tf.textContent=state.scannerTf;frame.src='https://www.tradingview.com/widgetembed/?symbol='+encodeURIComponent(tv)+'&interval='+encodeURIComponent(interval)+'&hidesidetoolbar=1&symboledit=1&saveimage=0&toolbarbg=%23081118&hideideas=1&theme='+((localStorage.getItem('PMA_THEME')||'dark')==='light'?'light':'dark')+'&style=1&timezone=Etc%2FUTC'}
async function scanMarket(){
  const selected=state.symbol||markets[state.market][0];
  const requestMarket=state.market, requestTf=state.scannerTf;
  const statusEl=document.getElementById('scannerStatus');
  const cacheKey='SCAN_'+state.market+'_'+selected+'_'+state.scannerTf;
  const cached=fastCached(cacheKey);
  if(cached){
    renderScannerResult(cached,selected,true);
    if(statusEl)statusEl.textContent='Verified snapshot ready • refreshing in background…';
  } else if(statusEl)statusEl.textContent='Verified snapshot requested…';
  // Load the exact symbol first. The watchlist scan is deliberately separate so a
  // slow/unavailable second market can never block the market the user selected.
  try{
    const q=await apiFast('/signals/scan?market='+encodeURIComponent(state.market)+'&symbols='+encodeURIComponent(selected)+'&selected='+encodeURIComponent(selected)+'&timeframe='+encodeURIComponent(state.scannerTf));
    saveFastCached(cacheKey,q); renderScannerResult(q,selected,false);
    if(statusEl)statusEl.textContent='Live verified snapshot • watchlist refreshing in background…';
  }catch(e){
    if(statusEl)statusEl.textContent=cached?'Last verified snapshot shown • live refresh will retry':'Verified feed is warming • retrying automatically';
  }
  // Populate closest monitored setups without delaying the selected symbol.
  setTimeout(async()=>{
    try{
      const symbols=Array.from(new Set([selected,...markets[state.market].slice(0,7)])).slice(0,8).join(',');
      const q=await apiFast('/signals/scan?market='+encodeURIComponent(state.market)+'&symbols='+encodeURIComponent(symbols)+'&selected='+encodeURIComponent(selected)+'&timeframe='+encodeURIComponent(state.scannerTf));
      saveFastCached(cacheKey,q); if(state.market===document.querySelector('.chip.active')?.textContent||true) renderScannerResult(q,selected,true);
    }catch(e){}
  },120);
}
function renderScannerResult(q,selected,fromCache){
    const statusEl=document.getElementById('scannerStatus');
    let c=(q.opportunities||[]).find(x=>x.symbol===selected)||q.closest;
    if(c){
      // Once the backend confirms the trigger, freeze the entry/SL/TP for this setup.
      // Polling may update market context, but it must not move an active trade's levels.
      const lockKey=selected+'|'+state.scannerTf;
      const existing=state.scannerLock;
      if(existing && existing.key===lockKey){
        if(c.direction===existing.direction){
          c={...c,entry_zone:existing.entry_zone,stop_loss:existing.stop_loss,take_profit_1:existing.take_profit_1,take_profit_2:existing.take_profit_2,status:'ACTIVE',trade_state:'ACTIVE',next_signal_status:'TRIGGERED'};
        }else{
          state.scannerLock=null;
        }
      }
      if(c.status==='SIGNAL READY' && !state.scannerLock){
        state.scannerLock={key:lockKey,direction:c.direction,entry_zone:c.entry_zone,stop_loss:c.stop_loss,take_profit_1:c.take_profit_1,take_profit_2:c.take_profit_2,triggered_at:c.updated_at};
      }
    }
    if(statusEl)statusEl.textContent=q.message||'Verified market data loaded.';
    if(!c){
      const eta=document.getElementById('selectedEta');
      const zone=document.getElementById('selectedZone');
      const meta=document.getElementById('selectedMeta');
      const stats=document.getElementById('selectedStats');
      const details=document.getElementById('selectedDetails');
      const dir=document.getElementById('selectedDirection');
      if(eta)eta.textContent='NO VERIFIED MARKET DATA';
      if(zone)zone.textContent=q.message||'No verified candle response.';
      if(meta)meta.textContent='No verified candle response • no signal generated';
      if(stats)stats.innerHTML='';
      if(details)details.innerHTML='';
      if(dir)dir.textContent='NO DATA';
      renderTrendGrid(state.lastTrends||{});
      renderNearby(q.opportunities||[]);
      return;
    }
    const dir=document.getElementById('selectedDirection');
    if(dir){
      const label=(c.status==='ACTIVE'||c.status==='SIGNAL READY') ? c.direction : (c.status==='FORECAST'&&c.direction&&c.direction!=='NO TRADE' ? 'FORECAST '+c.direction : (c.direction&&c.direction!=='NO TRADE' ? 'WATCH '+c.direction : 'NO TRADE'));
      dir.textContent=label;
    }
    const eta=document.getElementById('selectedEta');
    const zone=document.getElementById('selectedZone');
    const meta=document.getElementById('selectedMeta');
    const stats=document.getElementById('selectedStats');
    const details=document.getElementById('selectedDetails');
    if(eta)eta.textContent=formatEntryEta(c);
    if(zone)zone.textContent=c.next_zone!=null?`${c.direction} • next ${c.zone_type||'zone'} at ${c.next_zone} • ${c.pips_to_next_zone??'—'} pips away${c.status==='FORECAST'?' • forecast, wait for the planned zone/rejection':''}`:'Waiting for the next qualifying zone.';
    if(meta)meta.textContent=`${c.candles_to_next_zone??'—'} candles • ${fmtDuration(c.estimated_minutes_to_next_zone)} • ${c.status||'WATCHING'} • ${c.timeframe||state.scannerTf} • updated ${new Date(c.updated_at).toLocaleTimeString()}`;
    if(stats)stats.innerHTML='<span><b>'+setupStrengthLabel(c.setup_strength)+'</b> setup strength</span><span><b>'+((c.trend_alignment||'—'))+'</b> trend alignment</span><span><b>'+((c.validation?.win_rate??'—'))+(c.validation?.win_rate!=null?'%':'')+'</b> historical validation</span><span><b>'+((c.validation?.samples??0))+'</b> samples</span>';
    if(details)details.innerHTML=`<div class="detail-grid"><div><small>${c.status==='FORECAST'?'Planned pullback zone':'Entry zone'}</small><b>${c.entry_zone??'—'}</b></div><div><small>Stop loss</small><b>${c.stop_loss??'—'}</b></div><div><small>TP1</small><b>${c.take_profit_1??'—'}</b></div><div><small>TP2</small><b>${c.take_profit_2??'—'}</b></div><div><small>Structure</small><b>${escapeHtml(c.structure||'—')}</b></div><div><small>Next signal</small><b>${escapeHtml(c.next_signal_status||'—')}</b></div><div><small>Trigger</small><b>${escapeHtml(c.next_signal_trigger||'—')}</b></div><div><small>RSI trigger</small><b>${c.rsi_trigger??'—'}</b></div><div><small>Support</small><b>${c.support??'—'}</b></div><div><small>Resistance</small><b>${c.resistance??'—'}</b></div></div><div class="notice" style="margin-top:12px"><b>Why this setup:</b> ${escapeHtml((c.reasons||[]).join(' • ')||'Waiting for more confluence.')}</div>`;
    state.lastTrends=c.trends||state.lastTrends||{};
    renderTrendGrid(state.lastTrends);
    renderNearby(q.opportunities||[]);
    const key='PMA_LAST_SIGNAL_'+selected;
    const previous=localStorage.getItem(key);
    if(c.status==='SIGNAL READY'&&previous!==String(c.updated_at||'')){addNotification('New scanner setup',`${selected} has a ${c.direction} setup ready for confirmation.`,'signal');localStorage.setItem(key,String(c.updated_at||''))}
}
function renderTrendGrid(trends={}){
  const el=document.getElementById('trendGrid');if(!el)return;
  const frames=[['15m','15 Minutes'],['30m','30 Minutes'],['1h','1 Hour'],['4h','4 Hours'],['1d','1 Day']];
  el.innerHTML=frames.map(([key,label])=>{const v=trends[key];const cls=v==='Bullish'?'bullish':v==='Bearish'?'bearish':v==='Neutral'?'neutral':'unavailable';return `<div class="trend-box ${cls}"><span>${label}</span><strong>${v||'Waiting'}</strong><small>${v?'Cached/verified context':'No recent snapshot yet'}</small></div>`}).join('')
}
function renderNearby(items){const el=document.getElementById('nearbySetups');if(!el)return;if(!items.length){el.innerHTML='<p class="muted">No verified setups are available yet.</p>';return}el.innerHTML=items.slice(0,8).map(x=>`<div class="near-row"><div><div class="near-symbol">${x.symbol} • ${x.direction||'NO TRADE'}</div><div class="muted">${x.status||'WATCHING'} • next ${x.next_zone_type||'zone'} • ${x.pips_to_next_zone??'—'} pips • ${x.candles_to_next_zone??'—'} candles</div></div><div class="near-eta">${formatEntryEta(x)}</div></div>`).join('')}
function notifyNear(symbol,detail){if(window.Notification&&Notification.permission==='granted')new Notification('Pips Master Academy',{body:symbol+' is approaching its '+detail+' zone.'});toast(symbol+' is approaching its '+detail+' zone')}

function calculator(){return `<div class="section"><h1 class="section-title">Trading Calculator Hub</h1><p class="lead">Use the tools below with your own numbers. Broker specifications can differ, so treat results as estimates.</p><div class="calc-tabs"><button class="chip active" data-calc="risk" onclick="setCalcTab('risk')">Risk</button><button class="chip" data-calc="pnl" onclick="setCalcTab('pnl')">Profit / Loss</button><button class="chip" data-calc="pip" onclick="setCalcTab('pip')">Pip Value</button><button class="chip" data-calc="rr" onclick="setCalcTab('rr')">R:R</button><button class="chip" data-calc="margin" onclick="setCalcTab('margin')">Margin</button><button class="chip" data-calc="compound" onclick="setCalcTab('compound')">Compounding</button></div><div id="calcPanel" class="card"></div><div class="grid3" style="margin-top:18px"><div class="card"><h3>Risk</h3><p class="muted">Understand your planned risk before using an entry idea.</p></div><div class="card"><h3>Position size</h3><p class="muted">Position size depends on your stop distance and instrument value.</p></div><div class="card"><h3>Planning</h3><p class="muted">Use the calculator alongside the scanner instead of treating a signal as a guarantee.</p></div></div></div>`}
function setCalcTab(tab){document.querySelectorAll('[data-calc]').forEach(b=>b.classList.toggle('active',b.dataset.calc===tab));const panel=document.getElementById('calcPanel');if(!panel)return;const forms={risk:`<div class="grid"><div class="field"><label>Balance</label><input id="cBal" type="number" value="1000"></div><div class="field"><label>Risk %</label><input id="cRisk" type="number" value="1" step="0.1"></div><div class="field"><label>Stop distance (pips/points)</label><input id="cStop" type="number" value="20"></div><div class="field"><label>Value per pip/point per lot</label><input id="cPipVal" type="number" value="10"></div></div><button class="btn" onclick="runCalc('risk')">Calculate</button>`,pnl:`<div class="grid"><div class="field"><label>Entry</label><input id="pEntry" type="number" value="1.1000" step="0.0001"></div><div class="field"><label>Exit</label><input id="pExit" type="number" value="1.1050" step="0.0001"></div><div class="field"><label>Lot size</label><input id="pLot" type="number" value="0.10" step="0.01"></div><div class="field"><label>Value per pip/point per lot</label><input id="pPip" type="number" value="10"></div></div><button class="btn" onclick="runCalc('pnl')">Calculate</button>`,pip:`<div class="grid"><div class="field"><label>Lot size</label><input id="vLot" type="number" value="0.10" step="0.01"></div><div class="field"><label>Value per pip/point per lot</label><input id="vPip" type="number" value="10"></div></div><button class="btn" onclick="runCalc('pip')">Calculate</button>`,rr:`<div class="grid"><div class="field"><label>Entry</label><input id="rEntry" type="number" value="100"></div><div class="field"><label>Stop loss</label><input id="rSl" type="number" value="95"></div><div class="field"><label>Take profit</label><input id="rTp" type="number" value="110"></div></div><button class="btn" onclick="runCalc('rr')">Calculate</button>`,margin:`<div class="grid"><div class="field"><label>Units / contract size</label><input id="mUnits" type="number" value="100000"></div><div class="field"><label>Price</label><input id="mPrice" type="number" value="1.1000" step="0.0001"></div><div class="field"><label>Leverage</label><input id="mLev" type="number" value="100"></div></div><button class="btn" onclick="runCalc('margin')">Calculate</button>`,compound:`<div class="grid"><div class="field"><label>Starting balance</label><input id="coStart" type="number" value="1000"></div><div class="field"><label>Return per period %</label><input id="coRate" type="number" value="2" step="0.1"></div><div class="field"><label>Number of periods</label><input id="coPeriods" type="number" value="12"></div></div><button class="btn" onclick="runCalc('compound')">Calculate</button>`};panel.innerHTML=forms[tab]+'<div id="calcResult" style="margin-top:18px"></div>'}
function runCalc(kind){const out=document.getElementById('calcResult');if(!out)return;let html='';if(kind==='risk'){const risk=+cBal.value*(+cRisk.value/100),lot=risk/(Math.max(+cStop.value,1e-9)*Math.max(+cPipVal.value,1e-9));html=`<div class="notice">Risk amount: <b>${risk.toFixed(2)}</b><br>Estimated position size: <b>${lot.toFixed(3)}</b> lots`;}else if(kind==='pnl'){const pips=Math.abs(+pExit.value-+pEntry.value);const pnl=pips*(+pLot.value)*(+pPip.value);html=`<div class="notice">Price distance: <b>${pips.toFixed(5)}</b><br>Estimated P/L: <b>${pnl.toFixed(2)}</b> in the value unit you entered.`;}else if(kind==='pip'){const val=(+vLot.value)*(+vPip.value);html=`<div class="notice">Estimated pip/point value: <b>${val.toFixed(2)}</b>`;}else if(kind==='rr'){const risk=Math.abs(+rEntry.value-+rSl.value),reward=Math.abs(+rTp.value-+rEntry.value);html=`<div class="notice">Risk distance: <b>${risk.toFixed(5)}</b><br>Reward distance: <b>${reward.toFixed(5)}</b><br>Risk-to-reward: <b>1 : ${reward/Math.max(risk,1e-9).toFixed(2)}</b>`;}else if(kind==='margin'){const margin=(+mUnits.value*+mPrice.value)/Math.max(+mLev.value,1);html=`<div class="notice">Estimated margin: <b>${margin.toFixed(2)}</b><br><span class="muted">Actual margin depends on the broker and instrument contract rules.</span>`;}else{const projected=+coStart.value*Math.pow(1+(+coRate.value/100),Math.max(0,+coPeriods.value));html=`<div class="notice">Illustrative projected balance: <b>${projected.toFixed(2)}</b><br><span class="muted">This is a mathematical projection, not a promise of returns.</span>`;}out.innerHTML=html+'</div>'}
function daytrade(){const tfs=['1m','5m','15m','1h','4h','1d'];return `<div class="section"><h1 class="section-title">Day Trade Monitor</h1><p class="lead">Sniper entries wait for the strategy's confirmation. A trend alone never opens a trade.</p><div class="card"><div class="field"><label>Trigger timeframe</label><select id="dayTf" onchange="state.dayTf=this.value;localStorage.setItem('PMA_DAY_TF',this.value);loadDayTrade()">${tfs.map(x=>`<option ${x===(state.dayTf||'15m')?'selected':''}>${x}</option>`).join('')}</select></div><div class="chips">${Object.keys(markets).map(x=>`<button class="chip ${state.market===x?'active':''}" onclick="state.market='${x}';page('daytrade')">${x}</button>`).join('')}</div><button class="btn alt" onclick="loadDayTrade()">↻ Refresh</button><span id="dayTradeStatus" class="muted" style="display:block;margin-top:8px">Instant cached view loads first; live verification continues in the background.</span></div><div id="dayTradeArea" class="grid3 trade-monitor-grid" style="margin-top:18px"></div><div id="tradeHistoryArea" style="margin-top:18px"></div></div>`}
function startDayTrade(){clearInterval(state.dayTradeTimer);loadDayTrade();state.dayTradeTimer=setInterval(loadDayTrade,60000)}
async function monitorTradeOutcomes(x){const setups=x?.setups||[];const active=readJson('PMA_ACTIVE_TRADES',{});for(const s of setups){if(s.status==='SIGNAL READY'&&s.direction&&Number.isFinite(Number(s.entry_zone))){const key=s.symbol+'|'+s.timeframe;if(!active[key])active[key]={symbol:s.symbol,market:state.market,timeframe:s.timeframe,direction:s.direction,entry:s.entry_zone,sl:s.stop_loss,tp:s.take_profit_1,opened_at:Date.now(),notifiedWeak:false};const a=active[key];const price=Number(s.last);const hitTP=s.direction==='BUY'?price>=Number(a.tp):price<=Number(a.tp);const hitSL=s.direction==='BUY'?price<=Number(a.sl):price>=Number(a.sl);if(hitTP||hitSL){const outcome=hitTP?'take_profit':'stop_loss';const doneKey='PMA_DONE_'+key+'_'+outcome;if(!localStorage.getItem(doneKey)){localStorage.setItem(doneKey,'1');api('/trade-monitor/history',{method:'POST',body:JSON.stringify({symbol:s.symbol,market:state.market,timeframe:s.timeframe,direction:s.direction,entry:Number(a.entry),stop_loss:Number(a.sl),take_profit:Number(a.tp),outcome,reason:hitTP?'Take profit reached':'Stop loss reached'})}).catch(()=>{});addNotification(s.symbol+' '+(hitTP?'take profit reached':'stop loss reached'),hitTP?'Trade reached the planned take-profit level.':'Trade reached the planned stop-loss level.','signal','daytrade')}delete active[key]}}else if(active[s.symbol+'|'+s.timeframe]){const key=s.symbol+'|'+s.timeframe,a=active[key],price=Number(s.last);const favorable=a.direction==='BUY'?price>Number(a.entry):price<Number(a.entry);if(favorable&&!a.notifiedWeak&&s.status!=='SIGNAL READY'){a.notifiedWeak=true;addNotification(s.symbol+' confirmation weakened','The sniper confirmation is no longer fully aligned while the trade is favorable. Review whether to close in profit rather than waiting for TP.','signal','daytrade')}}}localStorage.setItem('PMA_ACTIVE_TRADES',JSON.stringify(active));loadTradeHistory()}
async function loadDayTrade(){const area=document.getElementById('dayTradeArea');if(!area)return;const tf=state.dayTf||localStorage.getItem('PMA_DAY_TF')||'15m';const requestMarket=state.market;const symbols=markets[state.market]||[];const selected=symbols[0];const cacheKey='PMA_DAYTRADE_'+state.market+'_'+tf;const cached=readJson(cacheKey,null);const render=(x)=>{if(!x||state.market!==requestMarket||state.dayTf!==tf)return;const st=document.getElementById('dayTradeStatus');if(st)st.textContent=(x.cached?'Verified cached snapshot • ':'Live verified snapshot • ')+new Date(x.updated_at).toLocaleTimeString()+(x.errors?.length?' • '+x.errors.length+' unavailable':'');area.innerHTML=(x.setups||[]).map(s=>{const live=s.live_trade_state||'WAITING FOR CONFIRMATION';const cls=live.includes('BUY')||live.includes('PROFIT')?'trade-green':live.includes('LOSS')||s.status==='STOP LOSS'?'trade-red':'';const entry=Number(s.entry_zone),last=Number(s.last);const floating=Number.isFinite(entry)&&Number.isFinite(last)&&s.direction==='BUY'?(last>=entry?'FLOATING PROFIT':'FLOATING LOSS'):Number.isFinite(entry)&&Number.isFinite(last)&&s.direction==='SELL'?(last<=entry?'FLOATING PROFIT':'FLOATING LOSS'):'';const stateLabel=s.status==='SIGNAL READY'?(s.direction==='BUY'?'READY TO BUY':'READY TO SELL'):(floating||live);return `<article class="card day-card trade-card ${cls}"><div class="trade-status ${cls}">${escapeHtml(stateLabel)}</div><h2>${s.symbol}</h2><div class="big">${s.direction||'NO TRADE'}</div><p class="muted">Trigger ${s.timeframe||tf} • ${setupStrengthLabel(s.setup_strength)} • ${s.trend_alignment||'—'} context</p><div class="strategy-chips">${(s.strategy_confluence||[]).map(v=>`<span class="zone-badge">${escapeHtml(v)}</span>`).join('')||'<span class="zone-badge">Waiting for sniper confirmation</span>'}</div><div class="statline"><span>${s.status==='FORECAST'||s.status==='WAITING FOR PULLBACK'?'Planned pullback zone':'Entry'}</span><b>${s.entry_zone??'Waiting'}</b></div><div class="statline"><span>Stop loss</span><b>${s.stop_loss??'Waiting'}</b></div><div class="statline"><span>Take profit</span><b>${s.take_profit_1??'Waiting'}</b></div><div class="statline"><span>Live price</span><b>${s.last??'—'}</b></div><p class="muted">${escapeHtml(s.day_trade_reason||'Wait for pullback, rejection and sniper candle confirmation.')}</p>${s.status==='SIGNAL READY'?`<button class="btn alt" onclick="manualCloseTrade(${JSON.stringify(s.symbol)},${JSON.stringify(s.market||state.market)},${JSON.stringify(s.timeframe||tf)},${JSON.stringify(s.direction)},${JSON.stringify(s.entry_zone)},${JSON.stringify(s.stop_loss)},${JSON.stringify(s.take_profit_1)})">Close trade manually</button>`:''}</article>`}).join('')||'<div class="notice">No verified setup returned yet.</div>'};if(cached)render({...cached,cached:true});else area.innerHTML='<div class="notice">Loading selected market…</div>';const selectedUrl='/day-trade/plan?market='+encodeURIComponent(requestMarket)+'&symbols='+encodeURIComponent(selected)+'&timeframe='+encodeURIComponent(tf);try{const x=await apiFast(selectedUrl);localStorage.setItem(cacheKey,JSON.stringify(x));render(x);monitorTradeOutcomes(x)}catch(e){if(!cached){area.innerHTML='<div class="notice">Selected market is temporarily unavailable. Retrying automatically.</div>'}}setTimeout(()=>{if(state.market!==requestMarket||state.dayTf!==tf)return;const fullSymbols=symbols.slice(0,6).join(',');apiFast('/day-trade/plan?market='+encodeURIComponent(requestMarket)+'&symbols='+encodeURIComponent(fullSymbols)+'&timeframe='+encodeURIComponent(tf)).then(x=>{localStorage.setItem(cacheKey,JSON.stringify(x));render(x);monitorTradeOutcomes(x)}).catch(()=>{})},50)}

async function manualCloseTrade(symbol,market,timeframe,direction,entry,sl,tp){const last=Number(entry);const reason='Manual close requested by user';try{await api('/trade-monitor/history',{method:'POST',body:JSON.stringify({symbol,market,timeframe,direction,entry:Number(entry)||null,stop_loss:Number(sl)||null,take_profit:Number(tp)||null,outcome:'manual_close',reason})});addNotification(symbol+' manually closed','The trade was recorded in Daily Trade Monitor History.','signal','daytrade');toast('Trade close recorded');loadTradeHistory()}catch(e){toast(e?.message||'Could not record the trade close')}}
async function loadReferrals(){try{const x=await api('/referrals');document.getElementById('myMonthRefs').textContent=x.month_qualified??0;document.getElementById('myPendingRefs').textContent=x.pending??0;document.getElementById('myTotalRefs').textContent=x.qualified_total??0;document.getElementById('myRefPosition').textContent=x.position?('#'+x.position):'—';document.getElementById('myRefScore').textContent=x.month_qualified??0;document.getElementById('refRank').textContent=x.referral_rank||'—';document.getElementById('refRankFill').style.width=(x.referral_rank_progress??0)+'%';document.getElementById('refRankNote').textContent=x.next_referral_rank?`${x.referral_rank_progress}% toward ${x.next_referral_rank}`:'Top referral rank reached';const rows=x.monthly_leaderboard||[];const podium=[rows.find(r=>r.rank===2),rows.find(r=>r.rank===1),rows.find(r=>r.rank===3)];['podium-second','podium-first','podium-third'].forEach((cls,i)=>{const card=document.querySelector('.'+cls);const r=podium[i];if(card&&r){card.querySelector('h2').textContent=(i===0?'2nd':i===1?'1st':'3rd')+' Place — '+r.username;card.querySelector('.big').textContent=r.qualified}});document.getElementById('refLeaderboard').innerHTML=rows.map(r=>`<div class="statline"><span>#${r.rank} ${escapeHtml(r.username)}</span><b>${r.qualified}</b></div>`).join('')||'<p class="muted">No qualified referrals recorded yet this month.</p>'}catch(e){const el=document.getElementById('refLeaderboard');if(el)el.innerHTML='<div class="notice">Referral information is temporarily unavailable.</div>'}}
function community(){const leave=state.user?.role==='admin'?'':`<button class="btn ghost" onclick="leaveCommunity()">Leave community</button>`;return `<div class="section"><div class="card"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap"><div style="display:flex;align-items:center;gap:12px"><img id="communityAvatar" class="avatar" style="width:58px;height:58px;border-width:2px" src="https://ui-avatars.com/api/?name=PMA&background=0d1b25&color=41e6a4" alt="Community"><div><h1 id="communityName" class="section-title" style="margin:0">PMA Community</h1><p id="communityBio" class="muted" style="margin:3px 0">Group chat • learning • market discussion</p></div></div><div style="display:flex;gap:7px;flex-wrap:wrap"><button class="btn alt" onclick="loadCommunity()">↻ Refresh</button><button class="btn alt" onclick="showCommunityInfo()">ⓘ Info</button>${leave}<span id="lockState" class="lock">🔓 Open</span></div></div><div id="communityGate" style="margin-top:14px"></div><div id="communityWorkspace" class="hidden"><div id="communityMembers" class="member-strip"></div><div class="filters"><input id="communitySearch" class="search" placeholder="Search inside community..." oninput="searchCommunity(this.value)"><button class="btn alt" onclick="searchCommunity('')">Clear</button><button class="btn ghost" onclick="toast('Voice/video calls need live WebRTC signalling; chat permissions are active now.')">📞 Voice</button><button class="btn ghost" onclick="toast('Voice/video calls need live WebRTC signalling; chat permissions are active now.')">🎥 Video</button></div><div id="messages" class="msgbox"></div><div class="filters"><input id="msgInput" class="search" placeholder="Write a message..."><label class="file-btn">📷 Photo / 🎥 Video<input id="mediaInput" type="file" accept="image/*,video/*" class="hidden" onchange="previewMessageMedia(event)"></label><button class="btn" onclick="sendMsg()">Send</button></div><div id="mediaPreview" class="media-preview"></div><div id="communityAdminPanel"></div></div></div></div>`}
async function loadCommunity(){const gate=document.getElementById('communityGate');const workspace=document.getElementById('communityWorkspace');if(!gate)return;try{const cached=readJson('PMA_COMMUNITY_STATUS_CACHE',null);if(cached){applyCommunityStatus(cached,gate,workspace);if(cached.approved)loadMessages()}const st=await apiFast('/community/status');localStorage.setItem('PMA_COMMUNITY_STATUS_CACHE',JSON.stringify(st));applyCommunityStatus(st,gate,workspace)}catch(e){const cached=readJson('PMA_COMMUNITY_STATUS_CACHE',null);if(!cached)gate.innerHTML='<div class="notice">Community access will retry automatically.</div>'}}
function applyCommunityStatus(st,gate,workspace){const s=st.settings||{};const name=document.getElementById('communityName');const av=document.getElementById('communityAvatar');if(name)name.textContent=s.name||'PMA Community';const bio=document.getElementById('communityBio');if(bio)bio.textContent=s.bio||'A place for PMA members to learn, share and discuss the markets.';if(av&&s.profile_picture)av.src=s.profile_picture;const lock=document.getElementById('lockState');if(lock)lock.textContent=st.suspended?'⛔ Suspended':st.pending?'🕒 Pending':'🔓 Open';if(st.approved){gate.innerHTML='';workspace?.classList.remove('hidden');loadMessages();if(state.user?.role==='admin')loadCommunityAdmin();}else{workspace?.classList.add('hidden');gate.innerHTML=st.suspended?'<div class="notice">Your community access is suspended. Contact the administrator.</div>':`<div class="notice"><b>${st.pending?'Join request pending':'Community access required'}</b><p class="muted">${st.pending?'Your request has been sent to the administrator.':'Request access before you can view or post in the community.'}</p>${!st.pending?'<button class="btn" onclick="requestCommunityJoin()">Request to Join</button>':''}</div>`}}

async function requestCommunityJoin(){try{const x=await api('/community/join',{method:'POST',body:JSON.stringify({action:'request'})});toast(x.status==='pending'?'Join request sent to the administrator.':'Community access confirmed.');loadCommunity()}catch(e){toast(e?.message||'Could not request community access')}}
async function searchCommunity(q){try{const x=await api('/community/messages?q='+encodeURIComponent(q||''));renderMessages(x.messages||[])}catch(e){toast(e?.message||'Search unavailable')}}
async function loadMessages(){const cached=readJson('PMA_COMMUNITY_MESSAGES_CACHE',null);if(cached){renderMessages(cached.messages||[]);renderCommunityMembers(readJson('PMA_COMMUNITY_MEMBERS_CACHE',[]))}try{const [x,m]=await Promise.all([apiFast('/community/messages'),apiFast('/community/members')]);localStorage.setItem('PMA_COMMUNITY_MESSAGES_CACHE',JSON.stringify(x));localStorage.setItem('PMA_COMMUNITY_MEMBERS_CACHE',JSON.stringify(m.members||[]));renderMessages(x.messages||[]);renderCommunityMembers(m.members||[]);if(typeof lockState!=='undefined')lockState.textContent=x.locked?'🔒 Locked':'🔓 Open'}catch(e){if(!cached)renderMessages([])}}
function renderCommunityMembers(members){const el=document.getElementById('communityMembers');if(!el)return;el.innerHTML='<div class="muted" style="margin-bottom:6px">Members • '+members.length+'</div>'+(members||[]).map(m=>`<button class="chip" onclick="mentionCommunityMember(${JSON.stringify(m.username)})">@${escapeHtml(m.username)}${m.role==='admin'?' • Admin':''}</button>`).join('')||'<span class="muted">No approved members yet.</span>'}
function mentionCommunityMember(username){const input=document.getElementById('msgInput');if(!input)return;input.value=(input.value?input.value+' ':'')+'@'+username+' ';input.focus()}
async function leaveCommunity(){if(state.user?.role==='admin'){toast('The administrator cannot leave the community.');return}if(!confirm('Leave the PMA Community?'))return;try{await api('/community/leave',{method:'POST'});localStorage.removeItem('PMA_COMMUNITY_STATUS_CACHE');toast('You left the community.');loadCommunity()}catch(e){toast(e?.message||'Could not leave the community')}}
function renderMessages(list){const el=document.getElementById('messages');if(!el)return;el.innerHTML=list.map(m=>`<div class="msg ${m.username===state.user.username?'right':''}"><b>${escapeHtml(m.username||'Member')}</b> <span class="muted">${escapeHtml(m.pma_id||'')}</span>${m.reply_to?`<div class="zone-badge">↪ Reply to ${escapeHtml(m.reply_to.username)}: ${escapeHtml(m.reply_to.text||'').slice(0,80)}</div>`:''}<br>${escapeHtml(m.text||'')}${m.media_data?(m.media_type||'').startsWith('video')?`<video class="message-media" controls src="${m.media_data}"></video>`:`<img class="message-media" src="${m.media_data}" alt="Shared media">`:''}<small class="muted"> ${escapeHtml(m.time||'just now')}</small><div class="chips" style="margin-top:6px"><button class="btn ghost" onclick="replyToMessage(${m.id},${JSON.stringify(m.username)},${JSON.stringify(m.text||'')})">↩ Reply</button>${m.username===state.user.username||state.user.role==='admin'?`<button class="btn ghost" onclick="deleteCommunityMessage(${m.id})">Delete</button>`:''}</div></div>`).join('')||'<p class="muted">No messages yet.</p>'}
async function loadCommunityAdmin(){const el=document.getElementById('communityAdminPanel');if(!el)return;try{const x=await api('/admin/community/members');const members=x.members||[];const pending=members.filter(m=>m.status==='pending');el.innerHTML=`<div class="card" style="margin-top:16px"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><h3 style="margin:0">Administrator controls</h3><p class="muted">${members.length} members • ${pending.length} pending requests</p></div><button class="btn alt" onclick="loadCommunityAdmin()">Refresh members</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Member</th><th>Status</th><th>Warnings</th><th>Action</th></tr></thead><tbody>${members.map(m=>`<tr><td><b>${escapeHtml(m.username)}</b><br><small class="muted">${escapeHtml(m.pma_id)}</small></td><td>${escapeHtml(m.status)}</td><td>${m.warning_count||0}</td><td><div class="chips">${m.status==='pending'?`<button class="btn alt" onclick="moderateCommunity(${m.id},'approve')">Approve</button>`:''}${m.account_role!=='admin'?`<button class="btn ghost" onclick="moderateCommunity(${m.id},'warn')">Warn</button><button class="btn ghost" onclick="moderateCommunity(${m.id},'suspend')">Suspend</button><button class="btn ghost" onclick="moderateCommunity(${m.id},'remove')">Remove</button>`:''}${m.status==='suspended'||m.status==='removed'?`<button class="btn alt" onclick="moderateCommunity(${m.id},'restore')">Restore</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><div class="filters"><input id="communityNameInput" class="search" placeholder="Community name"><input id="communityBioInput" class="search" placeholder="Community bio"><label class="file-btn">🖼️ Group picture<input id="communityPicInput" type="file" accept="image/*" class="hidden" onchange="previewCommunityPicture(event)"></label><select id="disappearSelect" class="search" style="max-width:220px"><option value="0">Disappearing messages: Off</option><option value="86400">24 hours</option><option value="604800" selected>7 days</option></select><button class="btn" onclick="saveCommunitySettings()">Save group settings</button></div><div id="communityPicPreview"></div></div>`}catch(e){el.innerHTML=''}}
function replyToMessage(id,user,text){state.replyToId=id;const input=document.getElementById('msgInput');if(input){input.placeholder='Reply to '+user+'…';input.focus();input.dataset.reply=id;}}
async function deleteCommunityMessage(id){if(!confirm('Delete this message?'))return;try{await api('/community/messages/'+id,{method:'DELETE'});toast('Message deleted');loadMessages()}catch(e){toast(e?.message||'Could not delete message')}}
async function moderateCommunity(id,action){const note=action==='warn'?prompt('Warning note:','Please follow community rules.')||'Community warning':prompt(action+' note:')||'';try{await api('/admin/community/moderate',{method:'POST',body:JSON.stringify({user_id:id,action,note})});toast('Community moderation saved');loadCommunityAdmin()}catch(e){toast(e?.message||'Moderation failed')}}
function previewCommunityPicture(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{state.communityPicture=r.result;document.getElementById('communityPicPreview').innerHTML=`<img class="avatar" style="width:80px;height:80px" src="${r.result}" alt="Group preview">`};r.readAsDataURL(f)}
async function saveCommunitySettings(){try{const name=document.getElementById('communityNameInput')?.value||document.getElementById('communityName')?.textContent||'PMA Community';const bio=document.getElementById('communityBioInput')?.value||document.getElementById('communityBio')?.textContent||'';const seconds=Number(document.getElementById('disappearSelect')?.value||0);await api('/admin/community/settings',{method:'POST',body:JSON.stringify({name,bio,profile_picture:state.communityPicture||'',disappearing_seconds:seconds})});toast('Community settings saved');loadCommunity()}catch(e){toast(e?.message||'Could not save community settings')}}
function showCommunityInfo(){toast(state.user?.role==='admin'?'Administrator access is automatic. Members request access for approval. Community moderation, search, media, notifications and disappearing messages are enabled.':'Members can request access for approval. Community moderation, search, media, notifications and disappearing messages are enabled. Live voice/video calling still needs WebRTC signalling.')}
function previewMessageMedia(e){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Media must be under 5MB');e.target.value='';return}const r=new FileReader();r.onload=()=>{state.pendingMedia={data:r.result,type:file.type,name:file.name};mediaPreview.innerHTML=file.type.startsWith('video')?`<video controls src="${r.result}"></video>`:`<img src="${r.result}" alt="Selected media">`;};r.readAsDataURL(file)}
async function sendMsg(){const text=msgInput.value.trim();const media=state.pendingMedia;if(!text&&!media)return;const payload={text,media_data:media?.data||'',media_type:media?.type||'',reply_to_id:Number(msgInput.dataset.reply||state.replyToId||0)};try{await api('/community/messages',{method:'POST',body:JSON.stringify(payload)});addNotification('Community message sent','Your message was posted.')}catch(e){toast(e?.message||'Message could not be sent right now.')}msgInput.value='';msgInput.placeholder='Write a message...';delete msgInput.dataset.reply;state.replyToId=0;state.pendingMedia=null;mediaPreview.innerHTML='';loadMessages()}
function escapeHtml(s){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function profile(){const u=state.user;const pic=u.profile_picture||'assets/images/profile-placeholder.svg';const link=location.origin+location.pathname+'?ref='+encodeURIComponent(u.referral_code||'');const adminBlock=(u.role==='admin'&&state.serverVerified)?`<div class="card admin-panel"><h2>Admin Controls</h2><p class="muted">Administrator controls are available on this account.</p><div id="adminStatsInline" class="grid3"><div class="notice">Checking admin status…</div></div><div class="filters admin-status"><button class="btn" onclick="toggleLock()">Lock / Unlock Community</button><button class="btn alt" onclick="loadAdminStats()">Refresh admin status</button></div><div id="adminFeedbackInline" style="margin-top:14px"></div></div>`:'';return `<div class="section"><h1 class="section-title">My Profile</h1><p class="lead">Manage your personal details, referral link and academy information.</p><div class="profile-layout"><div class="card profile-photo-card"><img id="profileAvatar" class="avatar" src="${pic}" alt="Profile picture"><div class="profile-actions"><label class="btn alt" style="cursor:pointer">Change picture<input id="picInput" type="file" accept="image/*" class="hidden" onchange="previewPicture(event)"></label><button class="btn ghost" onclick="removePicture()">Remove</button></div><p class="muted" style="font-size:12px">Your profile picture is part of your account profile.</p></div><div class="card"><h2>Personal details</h2><div class="profile-form"><div class="field"><label>Full Name</label><input id="pfName" value="${escapeAttr(u.full_name||'')}"></div><div class="field"><label>Username</label><input id="pfUser" value="${escapeAttr(u.username||'')}"></div><div class="field"><label>Phone Number</label><input id="pfPhone" value="${escapeAttr(u.phone||'')}" placeholder="Optional"></div><div class="field"><label>Date of Birth</label><input id="pfDob" type="date" value="${escapeAttr(u.dob||'')}"></div><div class="field full"><label>Email</label><input class="readonly" value="${escapeAttr(u.email||'')}" readonly></div><div class="field"><label>PMA User ID</label><input class="readonly" value="${escapeAttr(u.pma_id||'')}" readonly></div><div class="field"><label>Account Role</label><input class="readonly" value="${u.role==='admin'?'Administrator':'Member'}" readonly></div></div><button class="btn" onclick="saveProfile()">Save profile</button><div class="divider"></div><h3>Change password</h3><div class="profile-form"><div class="field"><label>New Password</label><div class="password-wrap"><input id="newPass" type="password"><button class="eye-btn" type="button" onclick="togglePassword('newPass',this)">👁️</button></div></div><div class="field"><label>Confirm New Password</label><div class="password-wrap"><input id="newPass2" type="password"><button class="eye-btn" type="button" onclick="togglePassword('newPass2',this)">👁️</button></div></div></div><button class="btn alt" onclick="changePassword()">Update password</button></div></div>${adminBlock}<div class="grid3" style="margin-top:18px"><div class="card color-card"><h3>Your referral link</h3><div class="big">${escapeHtml(u.referral_code||'')}</div><p class="muted">Share this unique referral link with people you know.</p><div class="copy-row"><input class="search ref-link-field" value="${escapeAttr(link)}" readonly id="refLink" title="${escapeAttr(link)}"><button class="btn alt" onclick="copyReferral(document.getElementById('refLink').value)">Copy referral link</button></div></div><div class="card color-card"><h3>Account progress</h3><p class="muted">Your permanent academy level, XP, tasks, learning and referrals are stored with your account.</p><button class="btn alt" onclick="page('progress')">View My Progress</button></div><div class="card color-card"><h3>Feedback</h3><p class="muted">Tell us what is working, what is missing and what should be improved.</p><button class="btn alt" onclick="page('feedback')">Send Feedback</button></div></div></div>`}
function escapeAttr(s){return String(s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
async function persistProfile(){try{if(!localStorage.getItem('PMA_TOKEN'))return false;const x=await api('/auth/profile',{method:'PUT',body:JSON.stringify({full_name:state.user.full_name,username:state.user.username,phone:state.user.phone,dob:state.user.dob,profile_picture:state.user.profile_picture||''})});if(x.user){state.user={...state.user,...x.user};saveLocalUser(state.user);return true}}catch(e){}return false}
function previewPicture(e){const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){toast('Please choose an image under 2MB');return}const r=new FileReader();r.onload=async()=>{state.user.profile_picture=r.result;saveLocalUser(state.user);const avatar=document.getElementById('profileAvatar');if(avatar)avatar.src=r.result;const saved=await persistProfile();addNotification('Profile picture updated',saved?'Your new profile picture was saved to your account.':'Your new profile picture was saved on this browser.','account');toast(saved?'Profile picture saved':'Profile picture saved locally')};r.readAsDataURL(file)}
async function removePicture(){state.user.profile_picture='';saveLocalUser(state.user);const saved=await persistProfile();page('profile');addNotification('Profile picture removed',saved?'Your profile picture was removed from your account.':'Your profile picture was removed on this browser.','account');toast('Profile picture removed')}
async function saveProfile(){state.user.full_name=pfName.value.trim();state.user.username=pfUser.value.trim();state.user.phone=pfPhone.value.trim();state.user.dob=pfDob.value;saveLocalUser(state.user);const saved=await persistProfile();userMini.textContent='@'+state.user.username;addNotification('Profile saved',saved?'Your profile details were saved to your account.':'Your profile details were saved on this browser.','account');toast(saved?'Profile saved successfully':'Profile saved locally');const pos=document.getElementById('screen')?.scrollTop||0;page('profile',false);requestAnimationFrame(()=>{document.getElementById('screen').scrollTop=pos})}
async function changePassword(){if(newPass.value.length<8){toast('Password must be at least 8 characters');return}if(newPass.value!==newPass2.value){toast('Passwords do not match');return}try{await api('/auth/password',{method:'PUT',body:JSON.stringify({password:newPass.value})});toast('Password changed successfully');addNotification('Password updated','Your password was updated successfully.','security')}catch(e){toast('Password could not be saved to the account.')}newPass.value='';newPass2.value=''}
async function copyText(t){return copyReferral(t)}
async function copyReferral(t){let ok=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(String(t));ok=true}}catch(e){}if(!ok){const ta=document.createElement('textarea');ta.value=t;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();try{ok=document.execCommand('copy')}catch(e){}ta.remove()}if(ok){toast('Referral link copied');addNotification('Referral link copied','Your referral link is ready to share.','referral')}else{const input=document.getElementById('refLink');if(input){input.focus();input.select()}toast('Copy failed — the link is selected for you')}}
async function loadFeedbackSummary(){const el=document.getElementById('feedbackRatingSummary');if(!el)return;const cached=readJson('PMA_FEEDBACK_SUMMARY_CACHE',null);const render=x=>{if(!x)return;const n=x.count||0,avg=x.average||0;const d=x.distribution||{};el.innerHTML=`<div class="grid"><div class="card"><div class="muted">Average rating</div><div class="big">${avg.toFixed(2)} ★</div></div><div class="card"><div class="muted">Total feedback</div><div class="big">${n}</div></div></div><div class="rating-bars">${[5,4,3,2,1].map(r=>{const pct=n?Math.round((d[String(r)]||0)/n*100):0;return `<div class="rating-line"><span>${r} ★</span><div class="rating-track"><div class="rating-fill" style="width:${pct}%"></div></div><b>${pct}%</b></div>`}).join('')}</div>`};if(cached)render(cached);try{const x=await apiFast('/feedback/summary');localStorage.setItem('PMA_FEEDBACK_SUMMARY_CACHE',JSON.stringify(x));render(x)}catch(e){if(!cached)el.innerHTML='<div class="notice">Feedback rating is not available yet.</div>'}}
function feedback(){return `<div class="section"><div class="card"><h1 class="section-title">Feedback</h1><p class="lead">Tell us what you like, what is not working, or what you want added to Pips Master Academy.</p><div class="field"><label>Feedback type</label><select id="fbCategory"><option>General</option><option>Bug report</option><option>Feature request</option><option>Scanner / Day Trade</option><option>Learning</option><option>Community</option><option>Referral system</option></select></div><div class="field"><label>Rating</label><div class="feedback-rating">${[1,2,3,4,5].map(n=>`<button type="button" class="rating-choice ${n===5?'active':''}" data-rating="${n}" onclick="selectFeedbackRating(${n})">${n} ★</button>`).join('')}</div><input type="hidden" id="fbRating" value="5"></div><div class="field"><label>Your feedback</label><textarea id="fbMessage" placeholder="Tell us what happened or what you would like us to improve…"></textarea></div><button class="btn" onclick="submitFeedback()">Send Feedback</button><div id="fbMsg" class="form-msg"></div></div><div class="card" style="margin-top:18px"><h2>Your previous feedback</h2><div id="myFeedback"><div class="notice">Loading…</div></div></div></div>`}
function selectFeedbackRating(n){document.getElementById('fbRating').value=n;document.querySelectorAll('.rating-choice').forEach(b=>b.classList.toggle('active',Number(b.dataset.rating)===n))}
async function submitFeedback(){const message=fbMessage.value.trim();if(!message){fbMsg.textContent='Please write your feedback first.';fbMsg.className='form-msg error';return}try{await api('/feedback',{method:'POST',body:JSON.stringify({category:fbCategory.value,rating:Number(fbRating.value),message})});fbMessage.value='';fbMsg.textContent='Feedback sent successfully.';fbMsg.className='form-msg ok';addNotification('Feedback received','Your feedback was saved successfully.','feedback');loadMyFeedback()}catch(e){fbMsg.textContent=e?.message||'Feedback could not be saved.';fbMsg.className='form-msg error'}}
async function loadMyFeedback(){const el=document.getElementById('myFeedback');if(!el)return;try{const x=await api('/feedback');el.innerHTML=(x.feedback||[]).map(f=>`<div class="notification-item"><b>${escapeHtml(f.category)} • ${f.rating}★</b><p class="muted" style="margin:6px 0">${escapeHtml(f.message)}</p><small class="muted">${escapeHtml(f.time)} • ${escapeHtml(f.status)}</small></div>`).join('')||'<p class="muted">No feedback sent yet.</p>'}catch(e){el.innerHTML='<div class="notice">Your feedback history could not be loaded.</div>'}}

function toggleFaq(id){const el=document.getElementById(id);if(!el)return;const open=el.classList.toggle('open');el.previousElementSibling?.classList.toggle('open',open)}
function about(){const reviews=[['Amina Yusuf','https://randomuser.me/api/portraits/women/44.jpg','5.0','The layout makes the learning process feel much more organised. I can move from market education to analysis and then to the calculator without feeling lost.','5'],['Daniel Okoro','https://randomuser.me/api/portraits/men/32.jpg','4.8','I like how the academy brings several useful ideas together. The explanations are short enough to understand while still giving me a clear direction for what to study next.','5'],['Grace Mensah','https://randomuser.me/api/portraits/women/68.jpg','4.7','The community section gives the platform a more active feel, and having profile controls and referral tools in one place makes the experience easier to manage.','5'],['Samuel Adeyemi','https://randomuser.me/api/portraits/men/46.jpg','4.5','The design feels modern and the market sections are easy to move through. I especially like the focus on preparation, risk and understanding the market instead of chasing random entries.','4'],['Chiamaka Eze','https://randomuser.me/api/portraits/women/65.jpg','4.2','There is a lot to explore, but the sections are clearly separated. The academy feels like a useful place to keep learning notes, market ideas and community discussions together.','4'],['David Mensah','https://randomuser.me/api/portraits/men/75.jpg','4.6','The workspace is easy to move through and the market tools are presented in a way that keeps the important information visible.','5'],['Sarah Bello','https://randomuser.me/api/portraits/women/49.jpg','4.4','I like the balance between the academy material, account tools and community area. It feels much more like one complete workspace.','4']];return `<div class="section"><h1 class="section-title">About Pips Master Academy</h1><p class="lead">Pips Master Academy is built around a simple idea: make market learning, analysis, planning and community interaction easier to access from one organised workspace. The platform is designed to keep the learning process practical, visually clear and focused on building better habits over time.</p><div class="grid3"><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=1200&q=85"><h3>Market structure</h3><p class="muted">Study trend direction, support and resistance, supply and demand, momentum and candle confirmation as connected parts of a bigger picture.</p></div><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1559526324-593bc073d938?auto=format&fit=crop&w=1200&q=85"><h3>Analysis with context</h3><p class="muted">Instead of relying on one candle, compare multiple timeframes and look for structure before considering an opportunity.</p></div><div class="card color-card"><img class="mini-img" src="https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?auto=format&fit=crop&w=1400&q=85"><h3>Risk awareness</h3><p class="muted">A setup is only one part of a trading plan. Position size, stop placement and discipline matter too.</p></div></div><div class="card" style="margin-top:18px"><h2>Forex in a few words</h2><p class="lead">Forex is the market where currencies are traded in pairs, such as EUR/USD or GBP/JPY. Traders compare the strength of one currency against another and may study trends, market structure, economic news, support and resistance, and risk before making a decision. Prices can move quickly, so learning and risk control are important.</p></div><div class="card" style="margin-top:18px"><h2>Contact Us</h2><p class="muted">Need help with your account, profile, referral link or community access? Contact Pips Master Academy customer service directly on Telegram.</p><a class="btn" href="https://t.me/Zinolee6" target="_blank" rel="noopener">💬 Telegram Customer Service</a></div><div class="card photo-section" style="margin-top:18px"><h2>Inside the learning workspace</h2><p class="muted">Different visual scenes keep the academy from feeling like one repeated green-and-black pattern.</p><div class="image-band"><img src="https://images.unsplash.com/photo-1518186285589-2f7649de83e0?auto=format&fit=crop&w=900&q=85" alt="Market research workspace"><img src="https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=900&q=85" alt="Data dashboard"><img src="https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=900&q=85" alt="Analytics screen"><img src="https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=900&q=85" alt="Modern workspace"></div></div><div class="card" style="margin-top:18px"><h2>Member Feedback Rating</h2><p class="muted">Live rating summary from feedback submitted through PMA.</p><div id="feedbackRatingSummary"><div class="notice">Loading live feedback rating…</div></div></div><div class="review-grid">${reviews.map(r=>`<article class="card review-card color-card"><div class="review-head"><img class="review-avatar" src="${r[1]}" alt="${r[0]}"><div><strong>${r[0]}</strong><div class="star">★★★★★ <span class="rating-number">${r[2]}</span></div></div></div><p class="quote">“${r[3]}”</p><p class="muted" style="font-size:12px">Sample testimonial • ${r[4]} star rating highlighted</p></article>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Questions & Answers</h2><div class="faq-list">${[['faq1','Are signals guaranteed?','No. Market conditions change and PMA setups depend on verified market data and confirmation.'],['faq2','How does a sniper entry work?','PMA waits for the strategy location, pullback or rejection, then the required confirmation candle or structure trigger before marking the setup ready.'],['faq3','Can I edit my profile?','Yes. Your saved phone number, date of birth, profile picture and other editable profile details are stored on your account.'],['faq4','Why can a trade close before take profit?','A setup can weaken or reverse before TP. PMA can notify the user to review/close manually when the monitored conditions deteriorate.'],['faq5','How do I contact support?','Use the Telegram Customer Service button above or the Feedback section inside the academy.']].map((f,i)=>`<div class="faq-item"><button class="faq-question" onclick="toggleFaq('${f[0]}')"><span>${i+1}. ${f[1]}</span><span>⌄</span></button><div id="${f[0]}" class="faq-answer"><p class="muted">${f[2]}</p></div></div>`).join('')}</div></div><div class="footer-note">Pips Master Academy • Learn first. Analyse clearly. Manage risk responsibly.</div></div>`}
function admin(){page('profile');return ''}
async function toggleLock(){try{const status=await api('/admin/status');if(!status.is_admin)throw Error('Administrator verification failed.');const x=await api('/admin/community/toggle',{method:'POST'});toast(x.locked?'Community locked':'Community opened');loadAdminStats();loadMessages()}catch(e){toast(e?.message||'Admin access required')}}
async function loadAdminStats(){const el=document.getElementById('adminStatsInline');if(!el)return;try{if(!state.serverVerified||state.user?.role!=='admin')throw Error('Admin access denied');const [status,x]=await Promise.all([api('/admin/status'),api('/admin/stats')]);el.innerHTML=`<div class="card"><div class="muted">Admin verification</div><div class="big">✅ Verified</div><p class="muted">${escapeHtml(status.email||state.user.email)}</p></div><div class="card"><div class="muted">Total users</div><div class="big">${x.total_users}</div></div><div class="card"><div class="muted">Active in 7 days</div><div class="big">${x.active_7d}</div></div><div class="card"><div class="muted">Community</div><div class="big">${x.community_locked?'🔒 Locked':'🔓 Open'}</div></div>`;const fb=document.getElementById('adminFeedbackInline');if(fb)fb.innerHTML=x.feedback_new?`<div class="notice">📩 ${x.feedback_new} new feedback item${x.feedback_new===1?'':'s'}.</div>`:'<div class="save-state">No new feedback yet.</div>'}catch(e){el.innerHTML=''}}
async function syncBackendProfile(){if(!localStorage.getItem('PMA_TOKEN'))return;try{const x=await api('/auth/profile');if(x.user){state.user={...state.user,...x.user};saveLocalUser(state.user);userMini.textContent='@'+state.user.username}}catch(e){}}
async function enableBrowserAlerts(){if(!('Notification' in window)){toast('This browser does not support notifications');return false}try{const permission=await Notification.requestPermission();state.browserAlertsReady=permission==='granted';toast(state.browserAlertsReady?'Browser alerts enabled':'Browser alerts were not enabled');return state.browserAlertsReady}catch(e){toast('Browser notification permission could not be requested');return false}}
function browserNotify(n){if(!('Notification' in window)||Notification.permission!=='granted')return;try{const note=new Notification(n.title||'Pips Master Academy',{body:n.text||'',tag:'pma-'+(n.id||Date.now())});note.onclick=()=>{window.focus();page(notificationTarget(n));note.close()}}catch(e){}}
function notificationTarget(n){return n.target_page||({referral:'referrals',community:'community',task:'progress',learning:'progress',signal:'signals',account:'profile',security:'profile',feedback:'feedback'}[n.type]||'home')}
function mergeNotificationHistory(list){const history=getNotificationHistory();const byKey=new Map(history.map(n=>[String(n.server_id||n.id),n]));for(const n of list){const k=String(n.server_id||n.id);if(!byKey.has(k)){history.unshift(n);byKey.set(k,n)}}const trimmed=history.slice(0,250);localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(trimmed));return trimmed}
function addInboxNotification(n){const dismissed=new Set(readJson('PMA_NOTIFICATION_DISMISSED_IDS',[]).map(String));if(dismissed.has(String(n.server_id||n.id)))return;const inbox=getNotificationInbox();inbox.unshift(n);localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(inbox.slice(0,60)))}
async function syncBackendNotifications(){try{const x=await apiFast('/notifications');const incoming=(x.notifications||[]).map(n=>({...n,server_id:n.id}));const previousIds=new Set(getNotificationHistory().map(n=>String(n.server_id||n.id)));mergeNotificationHistory(incoming);for(const n of incoming){if(!previousIds.has(String(n.server_id||n.id))){addInboxNotification(n);browserNotify(n)}}updateNotifBadge()}catch(e){}}
async function openNotification(index){const arr=getNotificationInbox();const n=arr[index];if(!n)return;const history=getNotificationHistory().map(x=>String(x.server_id||x.id)===String(n.server_id||n.id)?{...x,read:true}:x);localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(arr.filter((_,i)=>i!==index)));updateNotifBadge();if(n.server_id){try{await api('/notifications/read-one',{method:'POST',body:JSON.stringify({notification_id:Number(n.server_id)})})}catch(e){}}document.getElementById('notifPanel')?.classList.add('hidden');page(notificationTarget(n))}
function clearTopNotifications(){const inbox=getNotificationInbox();const ids=readJson('PMA_NOTIFICATION_DISMISSED_IDS',[]);const all=[...new Set([...ids,...inbox.map(n=>String(n.server_id||n.id))])];localStorage.setItem('PMA_NOTIFICATION_DISMISSED_IDS',JSON.stringify(all));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify([]));updateNotifBadge();toggleNotifications()}
function toggleNotifications(){const panel=document.getElementById('notifPanel');if(!panel)return;if(!panel.classList.contains('hidden')){panel.classList.add('hidden');return}const arr=getNotificationInbox();panel.innerHTML='<div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><h3 style="margin:0">Recent notifications</h3><button class="btn alt" onclick="enableBrowserAlerts()">🔔 Browser alerts</button></div>'+(arr.length?arr.slice(0,12).map((n,i)=>`<button class="notification-item ${n.read?'':'unread'}" onclick="openNotification(${i})" style="width:100%;text-align:left;color:inherit;cursor:pointer"><b>${escapeHtml(n.title)}</b><p style="margin:5px 0" class="muted">${escapeHtml(n.text)}</p><small class="muted">${escapeHtml(n.time||'')}</small></button>`).join(''):'<div class="notice" style="margin-top:10px">No new notifications in the top panel.</div>')+'<div style="display:flex;gap:8px;margin-top:10px"><button class="btn alt" onclick="page(\'notifications\')">View all</button><button class="btn alt clear-notifications" onclick="clearTopNotifications()">Clear</button></div>';panel.classList.remove('hidden')}
async function markNotificationsRead(){const history=getNotificationHistory().map(n=>({...n,read:true}));const inbox=getNotificationInbox().map(n=>({...n,read:true}));localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history));localStorage.setItem('PMA_NOTIFICATION_INBOX',JSON.stringify(inbox));updateNotifBadge();try{await api('/notifications/read')}catch(e){}}
function notificationCategories(){return ['All','Referrals','Tasks & Learning','Community','Signals','Account','Feedback']}
function notificationMatches(n,cat){if(cat==='All')return true;if(cat==='Referrals')return n.type==='referral';if(cat==='Tasks & Learning')return ['task','learning'].includes(n.type);if(cat==='Community')return n.type==='community';if(cat==='Signals')return n.type==='signal';if(cat==='Feedback')return n.type==='feedback';if(cat==='Account')return ['account','security','info'].includes(n.type);return true}
async function loadNotificationsPage(){
  const el=document.getElementById('notificationsArea'); if(!el)return;
  const render=()=>{const data=getNotificationHistory();const cat=state.notificationCategory||'All';const filtered=data.filter(n=>notificationMatches(n,cat));el.innerHTML=`<div class="card"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><div><h2 style="margin:0">Notification history</h2><p class="muted" style="margin:6px 0 0">Your history stays here even when you clear the small top-right notification panel.</p></div><div class="live-badge"><span class="live-dot"></span>${state.notificationsSyncing?'Syncing…':'Updated'}</div></div><div class="notification-tabs">${notificationCategories().map(c=>`<button class="notification-category ${c===cat?'active':''}" onclick="state.notificationCategory='${c}';loadNotificationsPage()">${c}</button>`).join('')}</div><div class="filters"><button class="btn alt" onclick="markNotificationsRead();loadNotificationsPage()">Mark all as read</button><button class="btn alt" onclick="enableBrowserAlerts()">Enable browser alerts</button></div><div class="notification-history-grid">${filtered.map(n=>`<button class="notification-item ${n.read?'':'unread'}" onclick="openHistoryNotification(${JSON.stringify(String(n.server_id||n.id))})" style="width:100%;text-align:left;color:inherit;cursor:pointer"><b>${escapeHtml(n.title)}</b><p style="margin:5px 0" class="muted">${escapeHtml(n.text)}</p><small class="muted">${escapeHtml(n.time||'')}</small><div style="font-size:11px;color:var(--mint);margin-top:5px">Open ${escapeHtml(notificationTarget(n))} →</div></button>`).join('')||'<div class="notice">No notifications in this category yet.</div>'}</div></div>`};
  render(); state.notificationsSyncing=true; render();
  syncBackendNotifications().finally(()=>{state.notificationsSyncing=false;render()});
}
function openHistoryNotification(id){const history=getNotificationHistory();const idx=history.findIndex(n=>String(n.server_id||n.id)===String(id));if(idx<0)return;const n=history[idx];history[idx]={...n,read:true};localStorage.setItem('PMA_NOTIFICATION_HISTORY',JSON.stringify(history));updateNotifBadge();if(n.server_id)api('/notifications/read-one',{method:'POST',body:JSON.stringify({notification_id:Number(n.server_id)})}).catch(()=>{});page(notificationTarget(n))}
function history(){return `<div class="section"><h1 class="section-title">Trading History</h1><p class="lead">Verified PMA trade and scanner history from the backend. By default, history older than 7 days is automatically removed.</p><div id="historySettings" class="card"><div class="notice">Loading history settings…</div></div><div id="historyArea" style="margin-top:16px"><div class="notice">Loading trading history…</div></div></div>`}
async function loadTradingHistoryPage(){const area=document.getElementById('historyArea'),settings=document.getElementById('historySettings');if(!area)return;const cached=readJson('PMA_FULL_HISTORY_CACHE',null);if(cached)renderTradingHistory(cached);try{const h=await apiFast('/history?days=7');localStorage.setItem('PMA_FULL_HISTORY_CACHE',JSON.stringify(h));renderTradingHistory(h)}catch(e){if(!cached)area.innerHTML='<div class="notice">No cached history is available yet. The verified history service will retry automatically.</div>'}try{const s=await apiFast('/history/settings');if(settings)settings.innerHTML=`<div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap"><div><h3 style="margin:0">Automatic history cleanup</h3><p class="muted" style="margin:5px 0">${s.enabled?'Enabled — records older than 7 days are deleted automatically.':'Off — history is retained until you choose to delete it.'}</p></div><button class="btn alt" onclick="toggleHistoryRetention()">${s.enabled?'Turn off 7-day deletion':'Turn on 7-day deletion'}</button></div>`}catch(e){if(settings)settings.innerHTML='<div class="notice">History settings will retry automatically.</div>'}}

function renderTradingHistory(x){const el=document.getElementById('historyArea');if(!el)return;const trades=x.trades||[],signals=x.signals||[],s=x.summary||{};el.innerHTML=`<div class="grid"><div class="card"><div class="muted">Total trades</div><div class="big">${s.total_trades??trades.length}</div></div><div class="card"><div class="muted">Profitable trades</div><div class="big trade-green">${s.profitable_trades??0}</div></div><div class="card"><div class="muted">Losing trades</div><div class="big trade-red">${s.losing_trades??0}</div></div><div class="card"><div class="muted">Profit rate</div><div class="big">${s.profit_rate??0}%</div></div></div><div class="grid" style="margin-top:14px"><div class="card"><div class="muted">Loss rate</div><div class="big">${s.loss_rate??0}%</div></div><div class="card"><div class="muted">Total profit outcomes</div><div class="big trade-green">${s.total_profit_trades??0}</div></div><div class="card"><div class="muted">Total loss outcomes</div><div class="big trade-red">${s.total_loss_trades??0}</div></div><div class="card"><div class="muted">Net outcome</div><div class="big">${s.net_outcome??0}</div></div></div><div class="notice" style="margin-top:14px">Profit/loss percentages are calculated from closed trades with a clear profit or loss outcome. The current journal does not store account balance, lot size or currency P/L, so no fake money value is displayed.</div><div class="card" style="margin-top:14px"><h2>Trade outcomes</h2><div class="table-wrap"><table class="table"><thead><tr><th>Market</th><th>Symbol</th><th>TF</th><th>Direction</th><th>Outcome</th><th>Time</th></tr></thead><tbody>${trades.map(t=>`<tr><td>${escapeHtml(t.market)}</td><td>${escapeHtml(t.symbol)}</td><td>${escapeHtml(t.timeframe)}</td><td>${escapeHtml(t.direction)}</td><td>${escapeHtml(t.outcome)}</td><td>${new Date((t.closed_at||0)*1000).toLocaleString()}</td></tr>`).join('')||'<tr><td colspan=6 class="muted">No closed trades recorded.</td></tr>'}</tbody></table></div></div><div class="card" style="margin-top:14px"><h2>Scanner / Service History</h2><div class="table-wrap"><table class="table"><thead><tr><th>Market</th><th>Symbol</th><th>TF</th><th>Direction</th><th>Status</th><th>Strength</th><th>Time</th></tr></thead><tbody>${signals.map(r=>`<tr><td>${escapeHtml(r.market)}</td><td>${escapeHtml(r.symbol)}</td><td>${escapeHtml(r.timeframe)}</td><td>${escapeHtml(r.direction)}</td><td>${escapeHtml(r.status)}</td><td>${r.setup_strength??'—'}%</td><td>${new Date((r.created||0)*1000).toLocaleString()}</td></tr>`).join('')||'<tr><td colspan=7 class="muted">No scanner history recorded yet.</td></tr>'}</tbody></table></div></div>`}

async function toggleHistoryRetention(){try{const x=await api('/history/settings',{method:'POST',body:JSON.stringify({enabled:!((await apiFast('/history/settings')).enabled)})});toast(x.enabled?'7-day history deletion enabled':'Automatic history deletion turned off');loadTradingHistoryPage()}catch(e){toast(e?.message||'Could not change history retention')}}
function notifications(){return `<div class="section"><h1 class="section-title">Notifications</h1><p class="lead">Keep a full history of referrals, learning, tasks, community, scanner and account notifications.</p><div id="notificationsArea"><div class="notice">Loading…</div></div></div>`}
function startNotificationPolling(){clearInterval(state.notifTimer);state.notifTimer=setInterval(()=>{if(state.user)syncBackendNotifications()},10000)}
function toast(msg){toastEl.textContent=msg;toastEl.classList.remove('hidden');clearTimeout(window.tt);window.tt=setTimeout(()=>toastEl.classList.add('hidden'),2600)}
const toastEl=document.getElementById('toast');
function logout(){if(confirm('Do you really want to log out?')){api('/auth/logout',{method:'POST'}).catch(()=>{});localStorage.removeItem('PMA_TOKEN');state.user=null;state.serverVerified=false;addNotification('Signed out','You logged out successfully.','security');show('welcome')}}
async function bootstrapPMA(){apiFast('/health',{timeoutMs:15000}).catch(()=>{});migrateNotifications();state.notif=getNotificationHistory();updateNotifBadge();const token=localStorage.getItem('PMA_TOKEN');if(state.ref&&!token){show('signup');return}if(token){try{const x=await apiFast('/auth/profile');if(x.user){state.user=x.user;state.serverVerified=true;saveLocalUser(x.user);enterApp(false);return}}catch(e){localStorage.removeItem('PMA_TOKEN');state.user=null;state.serverVerified=false}}state.user=null;state.serverVerified=false;show('welcome')}
applyTheme();
bootstrapPMA();
document.addEventListener('keydown',e=>{if(e.key==='Enter'){if(document.getElementById('login')?.classList.contains('active'))login();else if(document.getElementById('signup')?.classList.contains('active'))signup()}});
window.addEventListener('beforeunload',()=>{const sc=document.getElementById('screen');if(state.user){localStorage.setItem('PMA_CURRENT_PAGE',state.page);localStorage.setItem('PMA_SCROLL_'+state.page);localStorage.setItem('PMA_MARKET',state.market);localStorage.setItem('PMA_SYMBOL',state.symbol)}});
async function softRefreshCurrentPage(){const sc=document.getElementById('screen');const pos=sc?.scrollTop||0;try{if(state.page==='signals')await scanMarket();else if(state.page==='daytrade')await loadDayTrade();else if(state.page==='progress')await loadProgress();else if(state.page==='referrals')await loadReferrals();else if(state.page==='community')await loadMessages();else if(state.page==='profile'){await syncBackendProfile();if(state.user?.role==='admin')await loadAdminStats()}else if(state.page==='feedback')await loadMyFeedback();else if(state.page==='notifications')await loadNotificationsPage();else page(state.page,true)}finally{requestAnimationFrame(()=>{const s=document.getElementById('screen');if(s)s.scrollTop=pos})}}
(function(){let startY=null,pulling=false;const badge=document.getElementById('pullRefresh');document.addEventListener('touchstart',e=>{const t=e.touches[0];if(!t||['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName))return;const sc=document.getElementById('screen');if(sc&&sc.scrollTop<=0){startY=t.clientY;pulling=true}},{passive:true});document.addEventListener('touchmove',e=>{if(!pulling||startY==null)return;const t=e.touches[0];const d=t.clientY-startY;if(d>10){const amount=Math.min(80,d*.7);badge.style.transform=`translateX(-50%) translateY(${Math.max(-20,amount-80)}px)`;badge.style.opacity=String(Math.min(1,d/90))}},{passive:true});document.addEventListener('touchend',async e=>{if(!pulling)return;const t=e.changedTouches[0];const d=(t?.clientY||0)-startY;pulling=false;startY=null;if(d>90){badge.classList.add('show');badge.textContent='↻ Updating…';await softRefreshCurrentPage();setTimeout(()=>{badge.classList.remove('show');badge.style.opacity='0';badge.style.transform='translateX(-50%) translateY(-80px)'},500)}else{badge.classList.remove('show');badge.style.opacity='0';badge.style.transform='translateX(-50%) translateY(-80px)'}})})();
